\[
\begin{aligned}
\rho\Delta x\Delta y\Delta z
\frac{v_{x|t+\Delta t}-v_{x|t}}{\Delta t}
={}&
\rho(\Delta y\Delta z\,v_x+\Delta z\Delta x\,v_y+\Delta x\Delta y\,v_z)v_{x|x}\\
&-\rho(\Delta y\Delta z\,v_x+\Delta z\Delta x\,v_y+\Delta x\Delta y\,v_z)v_{x|x+\Delta x}\\
&+\Delta y\Delta z\,\tau_{xx|x}
-\Delta y\Delta z\,\tau_{xx|x+\Delta x}\\
&+\Delta z\Delta x\,\tau_{yx|y}
-\Delta z\Delta x\,\tau_{yx|y+\Delta y}\\
&+\Delta x\Delta y\,\tau_{zx|z}
-\Delta x\Delta y\,\tau_{zx|z+\Delta z}\\
&+\Delta y\Delta z\,p_{x|x}
-\Delta y\Delta z\,p_{x|x+\Delta x}\\
&+\rho\Delta x\Delta y\Delta z\,g_x
\end{aligned}
\]

\[
\begin{aligned}
&\frac{\rho v_{x|t+\Delta t}-\rho v_{x|t}}{\Delta t}=\\
&-\frac{\rho v_xv_{x|x+\Delta x}-\rho v_xv_{x|x}}{\Delta x}
-\frac{\rho v_yv_{x|x+\Delta x}-\rho v_yv_{x|x}}{\Delta y}
-\frac{\rho v_zv_{x|x+\Delta x}-\rho v_zv_{x|x}}{\Delta z}\\
&-\frac{\tau_{xx|x+\Delta x}-\tau_{xx|x}}{\Delta x}
-\frac{\tau_{yx|y+\Delta y}-\tau_{yx|y}}{\Delta y}
-\frac{\tau_{zx|z+\Delta z}-\tau_{zx|z}}{\Delta z}\\
&-\frac{p_{x|x+\Delta x}-p_{x|x}}{\Delta x}\\
&+\rho g_x
\end{aligned}
\]

\[
\begin{aligned}
\frac{\partial(\rho v_x)}{\partial t}
={}&
-\frac{\partial(\rho v_xv_x)}{\partial x}
-\frac{\partial(\rho v_yv_x)}{\partial y}
-\frac{\partial(\rho v_zv_x)}{\partial z}\\
&-\frac{\partial\tau_x}{\partial x}
-\frac{\partial\tau_y}{\partial y}
-\frac{\partial\tau_z}{\partial z}\\
&-\frac{\partial p_x}{\partial x}
+\rho g_x
\end{aligned}
\]

\[
\rho\left(
\frac{\partial v_x}{\partial t}
+v_x\frac{\partial v_x}{\partial x}
+v_y\frac{\partial v_x}{\partial y}
+v_z\frac{\partial v_x}{\partial z}
\right)
=
-\frac{\partial\tau_{xx}}{\partial x}
-\frac{\partial\tau_{yx}}{\partial y}
-\frac{\partial\tau_{zx}}{\partial z}
-\frac{\partial p_x}{\partial x}
+\rho g_x
\]

